ext('c10_eng_ch2',[
C("👦","कहानी का कथावाचक",["एक छोटा लड़का ख़ुद कहानी सुनाता है","स्कूल में इकोलॉजी पढ़कर उत्साहित","सबको सलाह देता है","पर ख़ुद पालन में कमज़ोर"],"यह कहानी एक छोटा लड़का ख़ुद सुनाता है, इसलिए इसे प्रथम पुरुष में लिखी कहानी कहते हैं। स्कूल में उसने पर्यावरण के बारे में पढ़ा है और वह जोश से भरा है। अब वह चाहता है कि घर का हर आदमी धरती बचाए। वह माँ को, पिता को और दोस्तों को सलाह देता रहता है। पर मज़ेदार बात यह है कि जब ख़ुद कुछ छोड़ने की बारी आती है, तो उसे मुश्किल लगता है। लेखिका जोन लेक्सो ने इसी बात को हल्के-फुल्के हास्य के साथ दिखाया है, ताकि हम हँसें भी और सोचें भी।"),
C("🏠","घर के लोग और सलाहें",["माँ से कहा: गाड़ी कम चलाओ","पिता से कहा: स्नोमोबाइल कम चलाओ","सब से कहा: बिजली और कागज़ बचाओ","सलाहें सही, पर तरीक़ा उपदेश वाला"],"लड़का अपनी माँ से कहता है कि गाड़ी कम चलाओ, क्योंकि उससे धुआँ निकलता है। पिता से कहता है कि स्नोमोबाइल यानी बर्फ़ पर चलने वाली गाड़ी बहुत ईंधन पीती है, इसे कम इस्तेमाल करो। सबको बिजली और कागज़ बचाने को कहता है। उसकी सारी सलाहें सही हैं। पर वह उन्हें उपदेश की तरह देता है, जैसे सब दोषी हों और वह अकेला सही। इसी वजह से घर के लोग चिढ़ने लगते हैं। इससे हमें सीख मिलती है कि दूसरों को बदलने से पहले ख़ुद का उदाहरण पेश करना ज़्यादा असरदार होता है।"),
C("😅","हास्य और व्यंग्य",["बच्चा ख़ुद अपनी सुविधा नहीं छोड़ता","बहाने ढूँढ़ता है","पाठक को हँसी आती है","छिपा संदेश: दोहरा मापदंड ठीक नहीं"],"कहानी की जान उसका हास्य है। जब लड़के को ख़ुद पैदल चलना पड़े या अपनी पसंद की कोई चीज़ छोड़नी पड़े, तो उसे बहाने सूझने लगते हैं। वह कहता है, यह तो ज़रूरी है, यह तो अलग बात है। पाठक को हँसी आती है, क्योंकि हम भी कई बार ऐसा ही करते हैं। इसे दोहरा मापदंड कहते हैं, यानी दूसरों के लिए एक नियम और अपने लिए दूसरा। व्यंग्य का मतलब है हँसी-हँसी में किसी कमज़ोरी की ओर इशारा करना। परीक्षा में कहानी का हास्य पूछा जाए, तो यही बिंदु लिखिए।"),
C("🌍","इकोलॉजी क्या है",["जीवों और पर्यावरण का आपसी रिश्ता","हवा, पानी, मिट्टी, पेड़, जानवर","एक की गड़बड़ी से सब प्रभावित","संतुलन बनाए रखना ज़रूरी"],"कहानी का शीर्षक है मी एंड द इकोलॉजी बिट, तो पहले इकोलॉजी का अर्थ समझ लीजिए। इकोलॉजी यानी पारिस्थितिकी। यह विज्ञान की वह शाखा है, जो जीव-जंतुओं और उनके पर्यावरण के आपसी रिश्ते का अध्ययन करती है। हवा, पानी, मिट्टी, पेड़ और जानवर सब एक-दूसरे से जुड़े हैं। अगर जंगल कटते हैं, तो पशु-पक्षी बेघर होते हैं, बारिश कम होती है और मिट्टी का कटाव बढ़ता है। इसलिए प्रकृति का संतुलन बनाए रखना ज़रूरी है। यही संतुलन बच्चा कहानी में सबको समझाने की कोशिश करता है।"),
C("🔌","ऊर्जा और ईंधन की बचत",["बिजली बचाने के आसान तरीक़े","एलईडी बल्ब, पंखा बंद करना","सौर ऊर्जा का प्रयोग","ईंधन बचाना यानी धरती बचाना"],"कहानी में ईंधन और बिजली की बचत की बात है। हम घर में ही कई आसान तरीक़ों से यह कर सकते हैं। कमरे से निकलते समय पंखा और बत्ती बंद कीजिए। एलईडी बल्ब लगाइए, जो कम बिजली लेते हैं। जहाँ संभव हो, पास की दूरी पैदल या साइकिल से तय कीजिए। बिहार में कई घरों में सौर लाइटें और सोलर पंप भी लग रहे हैं, जो साफ़ ऊर्जा देते हैं। जब हम ईंधन और बिजली बचाते हैं, तो प्रदूषण भी घटता है। इस तरह हर छोटी बचत धरती बचाने में योगदान बन जाती है।"),
C("💧","पानी बचाइए",["नल खुला मत छोड़िए","ब्रश करते समय नल बंद रखिए","बारिश का पानी इकट्ठा करें","पानी बर्बाद करना भविष्य छीनना है"],"पानी भी इकोलॉजी का बड़ा हिस्सा है। ब्रश करते समय नल खुला छोड़ देने से कई लीटर पानी बेकार बह जाता है। नहाने और कपड़े धोने में भी हम बहुत पानी बर्बाद करते हैं। इसके लिए ज़रूरत भर पानी लीजिए और टपकते नल की मरम्मत करवाइए। बारिश के पानी को इकट्ठा करना भी अच्छा तरीक़ा है। बिहार में जल जीवन हरियाली अभियान इसी सोच से चलाया जा रहा है। याद रखिए, पानी बर्बाद करना आने वाली पीढ़ियों से उनका हक़ छीनना है। इसलिए आज से ही आदत बदलिए।"),
C("✍️","जोन लेक्सो का परिचय",["अमेरिका की बाल-साहित्य लेखिका","बच्चों के लिए सरल कहानियाँ","हास्य के साथ सीख","बातचीत की शैली"],"अब लेखिका के बारे में जानिए। जोन लेक्सो अमेरिका की बाल-साहित्य की लेखिका थीं। उन्होंने बच्चों के लिए बहुत सी सरल और मज़ेदार कहानियाँ लिखीं। उनकी शैली की ख़ासियत है कि वे बच्चों की भाषा में, बातचीत की तरह कहानी कहती हैं। जैसे यहाँ लड़का ख़ुद बोल रहा है। उसमें छोटे वाक्य, रोज़मर्रा के शब्द और हल्का हास्य है। पर इसी हास्य के पीछे एक गंभीर संदेश छिपा है। परीक्षा में लेखिका का नाम, देश और उनकी शैली की एक-दो बातें अवश्य लिखिए।"),
C("📝","शब्दार्थ दोहराइए",["इकोलॉजी यानी पारिस्थितिकी","पॉल्यूशन यानी प्रदूषण","वेस्ट यानी बर्बादी","सेव, फ़्यूल, एनर्जी"],"आइए शब्द दोहरा लें। इकोलॉजी यानी पारिस्थितिकी, पॉल्यूशन यानी प्रदूषण, वेस्ट यानी बर्बादी, सेव यानी बचाना और फ़्यूल यानी ईंधन। इनके साथ एनर्जी यानी ऊर्जा, इलेक्ट्रिसिटी यानी बिजली और एनवायरनमेंट यानी पर्यावरण भी याद रखिए। एक अभ्यास कीजिए। हर शब्द से एक अंग्रेज़ी वाक्य बनाइए, जैसे वी शुड सेव एनर्जी, यानी हमें ऊर्जा बचानी चाहिए। और पॉल्यूशन इज़ हार्मफ़ुल, यानी प्रदूषण हानिकारक है। इन शब्दों का प्रयोग निबंध और पत्र में भी बहुत काम आएगा।"),
C("🧩","आज्ञा वाले वाक्य दोबारा",["क्रिया से सीधे वाक्य शुरू","नकार के लिए डोंट","विनम्रता के लिए प्लीज़","सेव वाटर, डोंट वेस्ट पेपर"],"आज का व्याकरण इम्पेरेटिव वाक्य यानी आज्ञा या सलाह वाले वाक्य हैं। इनमें कर्ता नहीं लिखा जाता, वाक्य सीधे क्रिया से शुरू होता है। जैसे सेव वाटर, यानी पानी बचाओ। स्विच ऑफ़ द लाइट, यानी बत्ती बंद करो। अगर मना करना हो, तो आगे डोंट लगाते हैं, जैसे डोंट वेस्ट पेपर। विनम्र बनाने के लिए प्लीज़ जोड़ सकते हैं, जैसे प्लीज़ क्लोज़ द डोर। पर्यावरण पर अपने पाँच इम्पेरेटिव वाक्य बनाइए। ये कहानी के विषय से भी जुड़े हैं और व्याकरण का अभ्यास भी हो जाएगा।"),
C("🗣️","कथन बदलना: सीधे और अप्रत्यक्ष",["सीधा कथन: उसने कहा, मैं पानी बचाऊँगा","अप्रत्यक्ष: उसने कहा कि वह पानी बचाएगा","काल और सर्वनाम बदलते हैं","कहानी में बहुत संवाद हैं"],"कहानी में लड़के और घर वालों के बहुत संवाद हैं, इसलिए डायरेक्ट और इनडायरेक्ट स्पीच भी याद कर लें। सीधे कथन में बोलने वाले के असली शब्द उद्धरण चिह्नों में लिखे जाते हैं, जैसे ही सेड, आई विल सेव वाटर। अप्रत्यक्ष कथन में हम बात को अपने शब्दों में बताते हैं, जैसे ही सेड दैट ही वुड सेव वाटर। यहाँ सर्वनाम आई से ही हो गया और विल से वुड हो गया। काल और सर्वनाम बदलने का यही नियम है। कहानी के दो संवाद लेकर इन्हें बदलने का अभ्यास कीजिए।"),
C("🌱","पर्यावरण के लिए हम क्या कर सकते हैं",["पेड़ लगाइए और उनकी देखभाल कीजिए","प्लास्टिक कम इस्तेमाल करें","कचरा अलग-अलग डालें","पराली न जलाएँ"],"अब कहानी से आगे की बात। पर्यावरण बचाने के लिए हम सब मिलकर बहुत कुछ कर सकते हैं। एक पेड़ लगाइए और उसकी देखभाल कीजिए, सिर्फ़ गड्ढा खोदकर छोड़ मत दीजिए। प्लास्टिक कम इस्तेमाल कीजिए। कचरे को गीले और सूखे में अलग-अलग डालिए। किसान भाई पराली न जलाएँ, क्योंकि उससे हवा बहुत ख़राब होती है। और सबसे ज़रूरी, कहानी के लड़के की तरह सिर्फ़ सलाह मत दीजिए, ख़ुद करके दिखाइए। जब आप उदाहरण बनते हैं, तो लोग अपने आप सीखते हैं।"),
C("❓","संभावित परीक्षा प्रश्न",["लेखिका कौन हैं","लड़के ने सबको क्या सलाह दी","कहानी का हास्य कहाँ है","कहानी का संदेश"],"परीक्षा के प्रश्न देखिए। पहला, लेखिका कौन हैं? उत्तर, जोन लेक्सो, अमेरिका की बाल-लेखिका। दूसरा, लड़के ने सबको क्या सलाह दी? उत्तर, कि गाड़ी और स्नोमोबाइल कम चलाओ, बिजली और कागज़ बचाओ। तीसरा, हास्य कहाँ है? उत्तर, जब लड़का ख़ुद अपनी सुविधा छोड़ने में बहाने बनाता है। चौथा, संदेश? उत्तर, पर्यावरण बचाना सबकी ज़िम्मेदारी है और इसकी शुरुआत ख़ुद से करनी चाहिए। उत्तर पूरे वाक्य में लिखिए।"),
Q("क्या आप भी कभी लड़के की तरह दूसरों को सलाह देते हैं पर ख़ुद पालन नहीं करते?","अपने अनुभव से उत्तर दीजिए और सोचिए कि अब से ख़ुद पालन करके उदाहरण कैसे बनेंगे।","एक सोचने वाला प्रश्न। क्या आप भी कभी लड़के की तरह दूसरों को सलाह देते हैं, पर ख़ुद उसका पालन नहीं करते? ईमानदारी से सोचिए। ... अपने अनुभव से उत्तर दीजिए और तय कीजिए कि अब से आप पहले ख़ुद पालन करके दूसरों के लिए उदाहरण बनेंगे। यही इस कहानी की सबसे बड़ी सीख है।"),
Q("कहानी में कथावाचक ने पर्यावरण बचाने के लिए माँ और पिता से क्या कहा?","माँ से गाड़ी कम चलाने और पिता से स्नोमोबाइल का ईंधन बचाने को कहा।","एक और प्रश्न। कहानी में कथावाचक ने माँ और पिता से क्या कहा? सोचिए। ... उसने माँ से गाड़ी कम चलाने को और पिता से स्नोमोबाइल का ईंधन बचाने को कहा। इसे पूरे वाक्य में लिखिए।"),
],7)
